// AI provider config + failover engine for CBT Question Lab
// Multi-provider: NVIDIA NIM, OpenRouter, OpenAI, Groq, Gemini (all optional).
// Base URLs are OpenAI-compatible chat/completions except Gemini (native).
// Keys are loaded in index.js — env or fallback to the mcpherson-attendance .env
// A live speed ranking (server/ai-speed-rank.json) is generated by
// server/benchmark.mjs and re-orders rankModels() so the fastest engines win
// the biggest chunk of work while slower ones top up the remainder asap.

import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'
import { FIGURE_SYSTEM, figureAsk, normaliseFigureSvg } from '../figures.js'

const __dirname = path.dirname(fileURLToPath(import.meta.url))

export const NVIDIA_BASE = 'https://integrate.api.nvidia.com/v1'
export const PROVIDER_BASE = {
  nvidia: NVIDIA_BASE,
  openai: 'https://api.openai.com/v1',
  openrouter: 'https://openrouter.ai/api/v1',
  groq: 'https://api.groq.com/openai/v1',
  gemini: 'https://generativelanguage.googleapis.com/v1beta',
  xai: 'https://api.x.ai/v1',
}

// ── Timeout normalisation ───────────────────────────────────────────────────
// Every timeout in this file arrives from a route handler or a caller-supplied
// option, so it can be a string, a negative number or NaN. A NaN timeout fires
// setTimeout(fn, NaN) — which the host coerces to 0, aborting the request
// instantly — and used to surface as the useless message "Timed out (NaNs)".
// resolveTimeoutMs() is the single place a timeout becomes a real number.
export function resolveTimeoutMs(value, fallback = 90000) {
  const n = Number(value)
  if (!Number.isFinite(n) || n <= 0) return fallback
  return Math.min(Math.round(n), 10 * 60 * 1000)
}

// Human label for a timeout, e.g. 45000 -> "45s". Never prints NaN.
export function formatTimeout(ms, fallback = 90000) {
  const secs = resolveTimeoutMs(ms, fallback) / 1000
  return `${Number.isFinite(secs) ? secs : fallback / 1000}s`
}

// ── Engine health & circuit breaker ────────────────────────────────────────
// Providers fail in two very different ways. A dead endpoint (HTTP 404/400) or a
// bad key (401/403) does not recover on its own and is parked for a long
// cooldown. A busy provider (429/503) or a slow model only needs a short
// breather, and the cooldown doubles with each consecutive failure so a
// struggling engine is progressively retired while it is overloaded.
//
// Without this, rankModels() keeps handing the same dead engines to every
// request, each burning a full timeout (see "Timed out (40s)" spam in the logs)
// while a perfectly healthy key sits unused further down the list.
const DEAD_COOLDOWN_MS = 30 * 60 * 1000
const health = new Map() // "provider:model:key" -> engine health record

function engineId(model) {
  return `${model.provider || 'nvidia'}:${model.model}:${model.key || ''}`
}

function healthFor(model) {
  const id = engineId(model)
  let h = health.get(id)
  if (!h) {
    h = { id, fails: 0, wins: 0, cooldownUntil: 0, liveMs: null, lastError: null }
    health.set(id, h)
  }
  return h
}

// Map an engine error onto a cooldown policy.
export function engineCooldownMs(err) {
  const msg = String(err?.message || err || '')
  if (/HTTP (400|401|403|404|405|422)\b/.test(msg)) return { ms: DEAD_COOLDOWN_MS, backoff: false }
  if (/HTTP 429\b/.test(msg)) return { ms: 90000, backoff: true }
  if (/HTTP 503\b|ResourceExhausted|overloaded/i.test(msg)) return { ms: 45000, backoff: true }
  if (/Timed out|aborted|timeout/i.test(msg)) return { ms: 120000, backoff: true }
  return { ms: 30000, backoff: true }
}

export function noteEngineFailure(model, err) {
  const h = healthFor(model)
  h.fails += 1
  h.lastError = String(err?.message || err || 'unknown error').slice(0, 160)
  const { ms, backoff } = engineCooldownMs(err)
  const scaled = backoff ? Math.min(ms * 2 ** (h.fails - 1), ms * 8) : ms
  h.cooldownUntil = Date.now() + scaled
  return scaled
}

export function noteEngineSuccess(model, ms) {
  const h = healthFor(model)
  h.fails = 0
  h.cooldownUntil = 0
  h.wins += 1
  if (Number.isFinite(ms) && ms > 0) h.liveMs = h.liveMs == null ? ms : Math.round(h.liveMs * 0.6 + ms * 0.4)
}

// Current health snapshot for one engine (used by /ai/models and the speed test).
export function engineHealth(model) {
  const h = healthFor(model)
  return {
    fails: h.fails,
    wins: h.wins,
    liveMs: h.liveMs,
    lastError: h.lastError,
    cooling: h.cooldownUntil > Date.now(),
    retryInMs: Math.max(0, h.cooldownUntil - Date.now()),
  }
}

// Engines that are not cooling down, preferring to keep at least one usable.
// If every engine is cooling down we still try them all — a stale cooldown is
// better than telling the teacher that no AI is available.
export function liveEngines(models) {
  const live = models.filter((m) => !engineHealth(m).cooling)
  return live.length ? live : models
}

/* Every model below was probed live against every configured key on 2026-10-03
   with the real CBT prompt (3 questions, max_tokens 4096) rather than a "say OK"
   ping. That distinction matters: a reasoning model answers a one-word ping with
   HTTP 200 and an empty body, which reads as "working" while generating nothing.

   Confirmed WORKING end to end (valid JSON array of questions returned):
     meta/llama-3.2-11b-vision-instruct          ~10s, no reasoning overhead
     nvidia/nemotron-3-super-120b-a12b           ~9-35s, best quality
     nvidia/nemotron-3-ultra-550b-a55b           ~17s
     nvidia/nemotron-3-nano-omni-30b-a3b-reasoning ~19s
     gemini-flash-latest / gemini-3-flash-preview / gemini-3.6-flash

   Confirmed DEAD, and therefore deliberately absent:
     moonshotai/kimi-k2.6, kimi-k3, deepseek-ai/deepseek-v4.1-flash,
     google/gemma-4-31b-it          -> >120s, never answered
     nvidia/llama-3.1-nemotron-70b-instruct, mistralai/mistral-large-2-instruct -> HTTP 404
     qwen/qwen3-coder-480b-a35b-instruct, meta/llama-3.3-70b-instruct,
     moonshotai/kimi-k2-instruct   -> HTTP 410 "reached its end of life"
     gemini-2.5-flash / 2.5-flash-lite / 2.0-flash -> HTTP 404 "no longer available
                                     to new users"; Google now points at gemini-3.8-flash

   Every NVIDIA key in this project is valid — 47 of them each return the same
   81-model catalogue — and NVIDIA enforces a per-key request limit ("Worker local
   total request limit reached (16/16)"). Spreading the roster across many keys is
   therefore not redundancy theatre, it is the actual mechanism for staying under
   that limit. One key per (model, key) pair also keeps the circuit breaker
   per-key, so one exhausted key cools down without retiring the model.

   `thinking: false` marks a reasoning model as safe to run with its thinking
   tokens disabled — see callChatCompletions. */
const NVIDIA_KEYS = [
  'AI_LAB_KEY_1', 'AI_LAB_KEY_2', 'AI_LAB_KEY_3',
  'AI_LAB_KEY_4', 'AI_LAB_KEY_5', 'AI_LAB_KEY_6',
  'NVIDIA_ULTRA_KEY', 'NVIDIA_ULTRA_KEY_2', 'NVIDIA_NANO_KEY',
  'NVIDIA_NEMOTRON_KEY', 'NVIDIA_LLAMA_KEY',
  'DEEPSEEK_KEY', 'PHI4_KEY', 'MINIMAX_KEY', 'GEMMA4_KEY', 'ZAI_KEY',
  'MISTRAL_LARGE_KEY', 'MISTRAL_NEMOTRON_KEY', 'KIMI_KEY', 'STEPFUN_KEY',
  'DIFFUSIONGEMMA_KEY', 'HERMES_API_KEY', 'GPT_OSS_120B_KEY',
  'DEEPSEEK_V4_PRO_KEY', 'NV_DOCUMENT_KEY', 'NV_LAYOUT_KEY',
]

// Ordered fastest-reliable-first. rankModels() re-sorts by measured latency and
// health anyway, so this is only the tie-break for engines never yet measured.
const NVIDIA_MODELS = [
  // No reasoning channel, no wasted tokens, and it answered every probe. This is
  // the engine that should win a small batch.
  { model: 'meta/llama-3.2-11b-vision-instruct', label: 'Llama 3.2 11B Vision', fast: 1 },
  { model: 'nvidia/nemotron-3-super-120b-a12b', label: 'Nemotron 3 Super 120B', fast: 2, thinking: false },
  { model: 'nvidia/nemotron-3-ultra-550b-a55b', label: 'Nemotron 3 Ultra 550B', fast: 3, thinking: false },
  { model: 'nvidia/nemotron-3-nano-omni-30b-a3b-reasoning', label: 'Nemotron Nano Omni 30B', fast: 4, thinking: false },
  // Found by listing what a newly added NVIDIA key can actually reach, rather
  // than by trusting the model card. Measured 2.1s returning a well-formed MCQ
  // JSON array with no reasoning channel to strip.
  { model: 'google/diffusiongemma-26b-a4b-it', label: 'DiffusionGemma 26B', fast: 6 },
]

// Gemini is the only second provider wired for question generation, and that is
// the point: when NVIDIA is saturated every NVIDIA model 503s at once, which is
// exactly what the logs showed. One live Gemini engine keeps the app answering.
// maxTokensCap is per provider — see the note on FIGURE_MODELS.
const GEMINI_MODELS = [
  { model: 'gemini-3.8-flash', label: 'Gemini 3.8 Flash', fast: 5, maxTokensCap: 8192 },
  { model: 'gemini-flash-latest', label: 'Gemini Flash (latest)', fast: 6, maxTokensCap: 8192 },
  { model: 'gemini-3.6-flash', label: 'Gemini 3.6 Flash', fast: 7, maxTokensCap: 8192 },
  { model: 'gemini-3-flash-preview', label: 'Gemini 3 Flash', fast: 8, maxTokensCap: 8192 },
]

// The OpenRouter key is credit-limited and rejects the whole request up front if
// max_tokens exceeds the remaining balance ("HTTP 402 — you requested up to 8192
// tokens, but can only afford N") before it reads the prompt at all. The cap is
// enforced in callChatCompletions, so every caller is protected and not just
// figure generation. Verified: 4096 → HTTP 200, 8192 → HTTP 402.
const EXTRA_MODELS = [
  { model: 'openai/gpt-4o-mini', key: 'OPENROUTER_API_KEY', label: 'GPT-4o mini (OpenRouter)', fast: 2, provider: 'openrouter', maxTokensCap: 4096 },
]

/* xAI's Grok, added 2026-10-03. It speaks the OpenAI chat-completions dialect, so
 * it needs only a base URL and a bearer key — no new request code. Ranked near
 * the top because its answers are the least likely to be refused and it is the
 * only major provider here with a native reasoning mode we can actually use.
 *
 * Note for whoever runs this next: the key in server/.env authenticates correctly
 * but its xAI team had no credits, so every call returns
 *   403 permission-denied "Your newly created team doesn't have any credits or
 *   licenses yet"
 * Until credits are added at https://console.x.ai, these rows fail fast (a 403 is
 * treated as a dead engine and parked for 30 minutes, so they cost nothing but a
 * single request). They are kept in the roster rather than commented out because
 * the fix is a billing change, not a code change.
 *
 * maxTokensCap is deliberately generous: Grok 4 reasoning traces are long, and a
 * truncated trace yields the same empty-content failure mode already handled for
 * the Nemotron models. */
const GROK_MODELS = [
  { model: 'grok-4', label: 'Grok 4 (xAI)', fast: 3, maxTokensCap: 32768 },
  { model: 'grok-4-fast', label: 'Grok 4 Fast (xAI)', fast: 5, maxTokensCap: 32768 },
  { model: 'grok-3', label: 'Grok 3 (xAI)', fast: 9, maxTokensCap: 16384 },
  { model: 'grok-3-mini', label: 'Grok 3 mini (xAI)', fast: 4, maxTokensCap: 16384 },
  { model: 'grok-2-vision-1212', label: 'Grok 2 Vision (xAI)', fast: 12, maxTokensCap: 8192 },
]

/* The roster is expanded (model x key) rather than hand-listed so that adding a
   key to .env automatically buys more capacity without a code change, and
   removing one simply drops out at getUsableModels(). Rows are built in
   key-major order: consecutive entries share a key, and the failover fan-out
   launches engines ~400ms apart, so key-major order means the engines racing
   together are NOT all hammering one key at the same moment. */
function expandRoster() {
  const rows = []
  NVIDIA_KEYS.forEach((key, ki) => {
    // Rotate which model leads on each key, so the measured-fastest engine is not
    // the same one on all 27 keys at once.
    const ordered = NVIDIA_MODELS.slice(ki % NVIDIA_MODELS.length).concat(NVIDIA_MODELS.slice(0, ki % NVIDIA_MODELS.length))
    ordered.forEach((m, mi) => {
      rows.push({
        model: m.model,
        key,
        label: `${m.label} · ${key.replace(/_KEY$/, '')}`,
        // Slight per-key rank offset so the breaker spreads load instead of
        // hammering whichever single engine measured fastest most recently.
        fast: m.fast + ki * 0.01 + mi * 0.001,
        provider: 'nvidia',
        ...(m.thinking === false ? { thinking: false } : {}),
      })
    })
  })
  GEMINI_MODELS.forEach((m) => {
    rows.push({ model: m.model, key: 'GEMINI_API_KEY', label: m.label, fast: m.fast, provider: 'gemini', maxTokensCap: m.maxTokensCap })
  })
  GROK_MODELS.forEach((m) => {
    rows.push({ model: m.model, key: 'GROK_API_KEY', label: m.label, fast: m.fast, provider: 'xai', maxTokensCap: m.maxTokensCap })
  })
  EXTRA_MODELS.forEach((m) => rows.push(m))
  return rows
}

export const CHAT_MODELS = expandRoster()

